referenceSolutions.javascript:
export function canFinish(courseCount        , prerequisites            )          {
  const edges            =Array.from({length:courseCount},()=>[]), indegree=Array        (courseCount).fill(0); for(const [course,pre] of prerequisites) { edges[pre].push(course); indegree[course]++; } const queue          =[]; for(let i=0;i<courseCount;i++) if(indegree[i]===0) queue.push(i); for(let i=0;i<queue.length;i++) for(const next of edges[queue[i]]) if(--indegree[next]===0) queue.push(next); return queue.length===courseCount;
}

